import './ActivityActionLike.css';
import { useEffect, useState } from 'react';
import process from 'process';
import {ReactComponent as HeartIcon} from './svg/heart.svg';
import {ReactComponent as HeartFilledIcon} from './svg/heart-filled.svg';
import { getAccessToken } from './lib/CheckAuth';

// Like / unlike toggle (backlog #18). Outline heart when not liked, solid
// theme-purple heart when liked (heart-filled.svg is heart.svg's outer
// outline without the cut-out). The server is the source of truth: the
// heart and the count change only after the API answers, so a failed request
// never leaves the UI showing something the database does not have.
export default function ActivityActionLike(props) {
  const [liked, setLiked] = useState(Boolean(props.liked));
  const [count, setCount] = useState(props.count || 0);
  const [busy, setBusy] = useState(false);

  // useState reads props only on first render. When the parent hands down
  // newer data for the same post (a feed reload, a profile change, "View N
  // more replies"), follow it so the heart never shows stale state.
  useEffect(() => {
    setLiked(Boolean(props.liked));
  }, [props.liked]);
  useEffect(() => {
    setCount(props.count || 0);
  }, [props.count]);

  const onclick = async (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (busy) return;

    const accessToken = await getAccessToken();
    if (!accessToken) {
      console.log('like: not signed in');
      return;
    }

    setBusy(true);
    try {
      const action = liked ? 'unlike' : 'like';
      const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/activities/${props.activity_uuid}/${action}`;
      const res = await fetch(backend_url, {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Authorization': `Bearer ${accessToken}`
        }
      });
      if (!res.ok) {
        console.log('like failed', res.status);
        return;
      }
      const data = await res.json();
      setLiked(Boolean(data.liked));
      setCount(data.likes_count);
    } catch (err) {
      console.log('like failed', err);
    } finally {
      setBusy(false);
    }
  };

  let counter;
  if (count > 0) {
    counter = <div className="counter">{count}</div>;
  }

  const classes = ['action', 'activity_action_heart'];
  if (liked) {
    classes.push('liked');
  }

  return (
    <div onClick={onclick} className={classes.join(' ')} role="button" aria-pressed={liked} aria-label={liked ? 'Unlike' : 'Like'}>
      {liked ? <HeartFilledIcon className='icon' /> : <HeartIcon className='icon' />}
      {counter}
    </div>
  );
}

import './ActivityItem.css';
import { useState } from 'react';

import ActivityContent  from '../components/ActivityContent';
import ActivityActionReply  from '../components/ActivityActionReply';
import ActivityActionRepost  from '../components/ActivityActionRepost';
import ActivityActionLike  from '../components/ActivityActionLike';
import ActivityActionShare  from '../components/ActivityActionShare';
import { getAccessToken } from './lib/CheckAuth';

export default function ActivityItem(props) {
  // Single-level threading. A child is an ActivityItem rendered by another
  // ActivityItem, which passes the thread root down as rootActivity.
  // Replying to a child targets the root, so a reply never gets replies.
  const isReply = Boolean(props.rootActivity);
  const replyTarget = props.rootActivity ?? props.activity;

  // The home feed sends at most 3 replies per root. When the root's count
  // is higher, the toggle fetches the full list in place from /replies.
  const [allReplies, setAllReplies] = useState(null);
  const [loadingReplies, setLoadingReplies] = useState(false);
  const [repliesError, setRepliesError] = useState(null);

  const feedReplies = props.activity.replies || [];
  const hiddenCount = (props.activity.replies_count || 0) - feedReplies.length;
  const shownReplies = allReplies ?? feedReplies;

  const loadAllReplies = async () => {
    setLoadingReplies(true);
    setRepliesError(null);
    try {
      const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/activities/${props.activity.uuid}/replies`;
      // Send the token when signed in so the API can fill liked_by_me;
      // without it every expanded reply showed an empty heart.
      const headers = {};
      const accessToken = await getAccessToken();
      if (accessToken) {
        headers['Authorization'] = `Bearer ${accessToken}`;
      }
      const res = await fetch(backend_url, { method: "GET", headers: headers });
      if (res.status !== 200) {
        throw new Error(`HTTP ${res.status}`);
      }
      const resJson = await res.json();
      setAllReplies(resJson);
    } catch (err) {
      console.log('load replies failed', err);
      setRepliesError('Could not load replies. Please try again.');
    } finally {
      setLoadingReplies(false);
    }
  };

  let replies;
  if (shownReplies.length > 0) {
    replies = <div className="replies">
                {shownReplies.map(reply => {
                return  <ActivityItem 
                  rootActivity={replyTarget}
                  setReplyActivity={props.setReplyActivity} 
                  setPopped={props.setPopped} 
                  key={reply.uuid} 
                  activity={reply} 
                  />
                })}
              </div>
  }

  let repliesToggle;
  if (!isReply && allReplies === null && hiddenCount > 0) {
    repliesToggle = <button type="button" className="replies_toggle" onClick={loadAllReplies} disabled={loadingReplies}>
                      {loadingReplies ? 'Loading replies...' : `View ${hiddenCount} more ${hiddenCount === 1 ? 'reply' : 'replies'}`}
                    </button>
  } else if (!isReply && allReplies !== null && allReplies.length > feedReplies.length) {
    repliesToggle = <button type="button" className="replies_toggle" onClick={() => setAllReplies(null)}>
                      Show fewer replies
                    </button>
  }

  return (
    <div className={isReply ? 'activity_item reply' : 'activity_item'}>
      <ActivityContent activity={props.activity} />
      <div className="activity_actions">
        <ActivityActionReply setReplyActivity={props.setReplyActivity} activity={replyTarget} setPopped={props.setPopped} activity_uuid={replyTarget.uuid} count={props.activity.replies_count}/>
        {!isReply && <ActivityActionRepost activity_uuid={props.activity.uuid} count={props.activity.reposts_count}/>}
        <ActivityActionLike activity_uuid={props.activity.uuid} count={props.activity.likes_count} liked={props.activity.liked_by_me}/>
        {!isReply && <ActivityActionShare activity_uuid={props.activity.uuid} />}
      </div>
      {replies}
      {repliesToggle}
      {repliesError && <div className="replies_error">{repliesError}</div>}
    </div>
  );
}

import './HomeFeedPage.css';
import React from "react";
import { useLocation, useNavigate } from 'react-router-dom';

import DesktopNavigation  from '../components/DesktopNavigation';
import DesktopSidebar     from '../components/DesktopSidebar';
import ActivityFeed from '../components/ActivityFeed';
import ActivityForm from '../components/ActivityForm';
import ReplyForm from '../components/ReplyForm';        

import { signOut } from 'aws-amplify/auth';
import { checkAuth, getAccessToken } from '../components/lib/CheckAuth';

export default function HomeFeedPage() {
  const [activities, setActivities] = React.useState([]);
  const [popped, setPopped] = React.useState(false);
  const [poppedReply, setPoppedReply] = React.useState(false);
  const [replyActivity, setReplyActivity] = React.useState({});
  const [user, setUser] = React.useState(null);
  const location = useLocation();
  const navigate = useNavigate();

const loadData = async () => {
    console.log('loadData called');
    const headers = {};

    // Get a fresh access token (auto-refreshes if expired)
    const accessToken = await getAccessToken();
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }

    const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/activities/home`;

    try {
      const res = await fetch(backend_url, {
        method: "GET",
        headers: headers,
      });

      const resJson = await res.json();
      if (res.status === 200) {
        setActivities(resJson)
      } else {
        console.log(res);
      }
    } catch (err) {
      console.log(err);
    }
  };

  const handleSignOut = async () => {
    try {
      await signOut();
      window.location.href = "/";
    } catch (error) {
      console.log('Error signing out: ', error);
    }
  };

  React.useEffect(() => {
    // Runs once on mount: check auth for the navigation, and load the feed.
    // loadData sends the token whenever a session exists, so one fetch
    // serves signed-in and signed-out visitors alike (backlog #22: a second
    // fetch after checkAuth duplicated every home request).
    checkAuth(setUser);
    loadData();
  }, []);

  // The Crud button on any other page navigates here with { compose: true }
  // (backlog #40). Open the form, then clear the flag with a replace so a
  // refresh or Back does not reopen it.
  React.useEffect(() => {
    if (location.state && location.state.compose) {
      setPopped(true);
      navigate(location.pathname, { replace: true, state: {} });
    }
  }, [location.state, location.pathname, navigate]);

  return (
    <article>
      <DesktopNavigation user={user} active={'home'} setPopped={setPopped} handleSignOut={handleSignOut} />
      <div className='content'>
        <ReplyForm 
          activity={replyActivity} 
          popped={poppedReply} 
          setPopped={setPoppedReply} 
          setActivities={setActivities} 
          activities={activities} 
        />
        <ActivityFeed 
          title="Home" 
          banner="home" 
          setReplyActivity={setReplyActivity} 
          setPopped={setPoppedReply} 
          activities={activities} 
        >
          {/* Compose form renders below the sticky Home banner (backlog #45). */}
          <ActivityForm
            popped={popped}
            setPopped={setPopped}
            setActivities={setActivities}
          />
        </ActivityFeed>
      </div>
      <DesktopSidebar user={user} />
    </article>
  );
}

import './UserFeedPage.css';
import React from "react";
import { useParams } from 'react-router-dom';

import DesktopNavigation  from '../components/DesktopNavigation';
import DesktopSidebar     from '../components/DesktopSidebar';
import ActivityFeed from '../components/ActivityFeed';
import ActivityForm from '../components/ActivityForm';
import ProfileHeading from '../components/ProfileHeading';
import ProfileForm from '../components/ProfileForm';
import ReplyForm from '../components/ReplyForm';

import { signOut } from 'aws-amplify/auth';
import { checkAuth, getAccessToken } from '../components/lib/CheckAuth';

export default function UserFeedPage() {
  const [activities, setActivities] = React.useState([]);
  const [profile, setProfile] = React.useState({});
  const [popped, setPopped] = React.useState(false);
  const [poppedProfile, setPoppedProfile] = React.useState(false);
  const [poppedReply, setPoppedReply] = React.useState(false);
  const [replyActivity, setReplyActivity] = React.useState({});
  const [user, setUser] = React.useState(null);

  const params = useParams();
  // The handle currently in the URL. A slow response for a profile the
  // user has already navigated away from must not overwrite the new one.
  const currentHandleRef = React.useRef(params.handle);
  currentHandleRef.current = params.handle;

  const loadData = async () => {
    const handle = params.handle;
    const headers = {};

    const accessToken = await getAccessToken();
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }

    try {
      const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/activities/@${handle}`
      const res = await fetch(backend_url, {
        method: "GET",
        headers: headers,
      });
      let resJson = await res.json();
      if (handle !== currentHandleRef.current) {
        return;
      }
      if (res.status === 200) {
        console.log('PROFILE DATA:', resJson);
        setProfile(resJson.profile);
        setActivities(resJson.profile.activities);
      } else {
        console.log(res)
      }
    } catch (err) {
      console.log(err);
    }
  };

  const handleSignOut = async () => {
    try {
      await signOut();
      window.location.href = "/";
    } catch (error) {
      console.log('Error signing out: ', error);
    }
  };

  React.useEffect(()=>{
    checkAuth(setUser);
  }, [])

  // Load on the first visit AND whenever :handle changes (backlog #48).
  // React Router keeps this component mounted for /@a -> /@b, so a
  // mount-only load kept showing the previous profile until a refresh.
  React.useEffect(()=>{
    setProfile({});
    setActivities([]);
    loadData();
  }, [params.handle])

  return (
    <article>
      <DesktopNavigation user={user} active={'profile'} setPopped={setPopped} handleSignOut={handleSignOut} />
      <div className='content'>
        <ActivityForm popped={popped} setActivities={setActivities} />
       <ProfileForm 
          profile={profile}
          popped={poppedProfile} 
          setPopped={setPoppedProfile}
          loadData={loadData}
        />
        {/* Reply popup, as on Home. Without it the reply icon on a profile did nothing. */}
        <ReplyForm
          activity={replyActivity}
          popped={poppedReply}
          setPopped={setPoppedReply}
          setActivities={setActivities}
          activities={activities}
        />
        <div className='activity_feed'>
          <ProfileHeading setPopped={setPoppedProfile} profile={profile} user={user} />
          <ActivityFeed
            setReplyActivity={setReplyActivity}
            setPopped={setPoppedReply}
            activities={activities}
          />
        </div>
      </div>
      <DesktopSidebar user={user} />
    </article>
  );
}
